[1201] = { en = "Theramore Spies", tier = 2,
  t = "Spionnen van Theramore",
  d = "De Horde en de Alliance hebben een onrustige wapenstilstand. Aan de randen zijn er kleine gevechten, en beide kanten voeren geheime acties uit tegen elkaar. Het is onze plicht om ervoor te zorgen dat de Horde bovenaan staat!$B$BNu is de kans om precies dat te doen.$B$BIndringers van de Alliance hebben posities ingenomen ten oosten van Brackenwall Village. Ze bespioneren het dorp en melden onze bewegingen aan Theramore. Dat kunnen we niet toestaan.$B$BZoek de indringers op en dood ze. Stuur hun bazen een duidelijke boodschap: we tolereren hun spionnen hier niet!",
  o = "Dood 9 Theramore Infiltrators en ga dan terug naar Nazeer Bloodpike in Brackenwall Village.",
  p = "Heb je de indringers gevonden, $N?",
  c = "Goed werk. Hun indringers zijn bekwaam, maar ze zijn niet goed genoeg om aan het waakzame oog van de Horde te ontsnappen!",
  g = { {"spionnen", "spies (spion)"}, {"onrustige", "uneasy (onrustig)"}, {"wapenstilstand", "truce"}, {"randen", "edges, outskirts (rand)"}, {"geheime", "secret, covert (geheim)"}, {"plicht", "duty"}, {"indringers", "infiltrators, intruders (indringer)"}, {"ingenomen", "taken (innemen)"}, {"bespioneren", "to spy on"}, {"toestaan", "to allow"}, {"tolereren", "to tolerate"}, {"bekwaam", "skilled, capable"}, {"waakzame", "watchful (waakzaam)"}, {"ontsnappen", "to escape"} },
},

[1202] = { en = "The Theramore Docks", tier = 2,
  t = "De haven van Theramore",
  d = "$N, twee van onze spionnen werden naar de haven van Theramore gestuurd om documenten van een schip te stelen. Ze kregen de papieren te pakken, maar werden ontdekt. Ze moesten de documenten in de zee gooien.$B$BLater ontsnapte één spion, maar hij kon de buit niet terughalen. Hij meldde zijn mislukking aan mij, en nu geef ik de taak aan jou.$B$BDe documenten zitten in een kist, ergens in het water onder de kades van Theramore. Vind die documenten, $N, en breng ze naar mij.",
  o = "Breng de Captain's Documents naar Nazeer Bloodpike in Brackenwall Village.",
  p = "Heb je de documenten gevonden, $N? Er staat informatie in die heel belangrijk is voor de stabiliteit van de Alliance, en dus ook heel belangrijk voor de veiligheid van de Horde.",
  c = "Ik prijs je, $N. Dit was geen makkelijke missie. Maar onze leiders vinden de documenten die je hebt gehaald erg waardevol.",
  g = { {"haven", "harbour, docks"}, {"te pakken kregen", "got hold of (te pakken krijgen)"}, {"ontdekt", "discovered (ontdekken)"}, {"buit", "prize, loot"}, {"meldde", "reported (melden)"}, {"mislukking", "failure"}, {"kades", "docks, quays (kade)"}, {"stabiliteit", "stability"}, {"veiligheid", "security, safety"}, {"prijs", "praise, commend (prijzen)"}, {"waardevol", "valuable"} },
},

[1238] = { en = "The Lost Report", tier = 2,
  t = "Het verloren rapport",
  d = "Terwijl je door de losse aarde zoekt, vind je de afgehakte hand van een orc. In de hand zit een buis van uitgesneden bot geklemd. En in de buis zit een stuk perkament met vlekken van aarde.$B$BHet perkament is een rapport van een orc die wekenlang de stad Theramore heeft bespioneerd.$B$BAls je het perkament vlug doorleest, is het duidelijk dat het naar de orc-spionnenmeester in Brackenwall Village moet.",
  o = "Breng het Spy's Report naar Nazeer Bloodpike in Brackenwall Village.",
  p = "Heb je iets voor me?",
  c = "Goed werk, $N. Onze agent, Marg Nighteye, was buiten Theramore gestationeerd. Hij had de opdracht om de stad te bespioneren.$B$BDit is zijn nieuwste rapport, en het is misschien zijn laatste. Door wat jij vertelt, vrees ik dat Marg in het moeras aan zijn einde is gekomen...",
  g = { {"losse", "loose (los)"}, {"afgehakte", "severed, chopped off (afhakken)"}, {"buis", "tube"}, {"uitgesneden", "carved (uitsnijden)"}, {"geklemd", "clutched, clamped (klemmen)"}, {"perkament", "parchment"}, {"vlekken", "stains (vlek)"}, {"bespioneerd", "spied on (bespioneren)"}, {"vlug doorleest", "quickly scan (doorlezen)"}, {"spionnenmeester", "spymaster"}, {"gestationeerd", "stationed (stationeren)"}, {"opdracht", "assignment, order"}, {"moeras", "swamp, marsh"}, {"aan zijn einde gekomen", "met his end"} },
},

[1239] = { en = "The Severed Head", tier = 2,
  t = "Het afgehakte hoofd",
  d = "Door hard te graven vind je het hoofd van een mannelijke orc. Het is ruw afgehakt bij de nek. Zijn lippen zijn bevroren in een grauw, en zijn donkere ogen staren uitdagend.",
  o = "Breng het Defiant Orc Head naar Nazeer Bloodpike in Brackenwall Village.",
  p = "Heb je nog iets anders te melden, $N?",
  c = "Dit is het hoofd van Marg Nighteye! Zoals ik vreesde, is hij dood.$B$BKijk naar de wond in zijn nek! Kan een wapen die ruwe snee hebben gemaakt, of heeft een beest onze agent gedood?$B$BDit is een raadsel dat we moeten oplossen, $N. We moeten ontdekken of de Alliance Marg heeft gedood!",
  g = { {"afgehakte", "severed (afhakken)"}, {"graven", "to dig"}, {"mannelijke", "male (mannelijk)"}, {"ruw", "roughly, raggedly"}, {"bevroren", "frozen (bevriezen)"}, {"grauw", "snarl"}, {"staren", "to stare"}, {"uitdagend", "defiantly"}, {"melden", "to report"}, {"vreesde", "feared (vrezen)"}, {"wond", "wound"}, {"snee", "cut"}, {"raadsel", "mystery, riddle"} },
},

[1240] = { en = "The Troll Witchdoctor", tier = 2,
  t = "De heksendokter van de trollen",
  d = "We moeten weten wat er rond de dood van Marg is gebeurd! En de enige manier om dat te weten, $N, is met de heksenmagie van de trollen.$B$BBreng het hoofd van Marg naar Kin'weelay in Stranglethorn Vale, in het Grom'gol Base Camp.$B$BKin'weelay is de machtigste heksendokter van de Darkspear-trollen. Als iemand met de geest van Marg Nighteye kan praten, is hij het.",
  o = "Breng het Defiant Orc Head naar Kin'weelay in het Grom'gol Base Camp in Stranglethorn Vale.",
  p = "Er hangt een boze geest om je heen, $gbroeder:zuster;. Wat brengt je bij Kin'weelay?",
  c = "Ah, nu zie ik het. De geest van deze orc is gebonden aan onze wereld. Hij kookt van woede, omdat een taak nog niet af is.$B$BNou, laten we eens praten met deze boze orc...",
  g = { {"heksendokter", "witch doctor"}, {"rond", "around, surrounding"}, {"heksenmagie", "witch magic"}, {"machtigste", "most powerful (machtig)"}, {"geest", "spirit, ghost"}, {"er hangt ... om je heen", "there is ... about you"}, {"gebonden", "bound (binden)"}, {"kookt van woede", "boils with rage (koken)"} },
},

[1251] = { en = "The Black Shield", tier = 2,
  t = "Het zwarte schild",
  d = "Een ijzeren schild hangt aan de afbrokkelende schoorsteen. Het is zwart geworden door het vuur dat door de herberg raasde. De schoorsteen is een van de weinige delen die nog over zijn van het gebouw dat ooit de Shady Rest Inn was.$b$bHet schild kan van de bakstenen van de schoorsteen worden gehaald.",
  o = "Breng het Blackened Iron Shield naar Krog in Brackenwall Village.",
  p = "Wat heb je daar, $n? Bewijs uit de resten van de Shady Rest Inn?",
  c = "Ik geef toe dat mensen een vreemde smaak hebben als het om versieren gaat, maar zouden ze een gewoon ijzeren schild gebruiken om hun open haard te versieren? Misschien hebben degenen die de herberg in brand hebben gestoken dit schild daar opgehangen.$b$bEen waarschuwing? Een dreigement?",
  g = { {"schild", "shield"}, {"afbrokkelende", "crumbling (afbrokkelen)"}, {"schoorsteen", "chimney"}, {"herberg", "inn"}, {"raasde", "raged (razen)"}, {"bakstenen", "bricks (baksteen)"}, {"bewijs", "evidence, proof"}, {"resten", "remains (rest)"}, {"ik geef toe", "I grant, I admit (toegeven)"}, {"versieren", "to decorate"}, {"open haard", "fireplace"}, {"in brand gestoken", "set on fire (in brand steken)"}, {"dreigement", "threat"} },
},

[1268] = { en = "Suspicious Hoofprints", tier = 2,
  t = "Verdachte hoefafdrukken",
  d = "Rijen hoefafdrukken lopen weg van het nog rokende skelet van de Shady Rest Inn. Je ziet er minstens een paar duidelijk, en er zijn nog meer rijen afdrukken die bijna onzichtbaar zijn in de zachte modder van het moeras.",
  o = "Meld de verdachte afdrukken bij de Shady Rest Inn aan Krog in Brackenwall Village.",
  c = "Hoefafdrukken... Het kunnen de quilboars zijn geweest, denk ik. Of misschien zelfs de centaurs. Er zijn er nogal wat van in de Barrens, en ik zou het niet vreemd vinden als zij zoiets hebben gedaan.$b$bHeb ik het je verteld? De herberg is niet alleen afgebrand... De vrouw en het jong van de eigenaar zijn gedood. Een nare zaak.$b$bToch zal ik Kagoro sturen om uit te zoeken waar de sporen naartoe gaan.",
  g = { {"verdachte", "suspicious (verdacht)"}, {"hoefafdrukken", "hoofprints (hoefafdruk)"}, {"rijen", "rows (rij)"}, {"rokende", "smoking (roken)"}, {"skelet", "skeleton"}, {"onzichtbaar", "invisible, imperceptible"}, {"modder", "mud"}, {"nogal wat", "quite a few"}, {"afgebrand", "burned down (afbranden)"}, {"het jong", "the young one, pup"}, {"eigenaar", "owner"}, {"een nare zaak", "bad business"}, {"sporen", "tracks (spoor)"} },
},

[1321] = { en = "The Black Shield", tier = 2,
  t = "Het zwarte schild",
  d = "Hmm... Ik zie niets bijzonders aan dit schild. Laten we Do'gol, de smid, er eens naar laten kijken. Misschien kan hij ons er meer over vertellen, maar ik zou er niet te veel op hopen...",
  o = "Laat het Blackened Iron Shield zien aan Do'gol in Brackenwall Village.",
  p = "Iets voor mij, $c?",
  c = "Dit is een goed schild. Heel sterk, zwaar, goed. Maar Do'gol heeft het niet nodig. Ik maak schilden, ik koop ze niet, $n.$b$bDat moet je weten.",
  g = { {"bijzonders", "out of the ordinary, special (bijzonder)"}, {"smid", "blacksmith"}, {"hopen op", "to hope for"}, {"schild", "shield"}, {"zwaar", "heavy"}, {"schilden", "shields (schild)"} },
},

[596] = { en = "Bloody Bone Necklaces", tier = 3,
  t = "Bloederige botkettingen",
  d = "Ik werd naar Grom'gol gestuurd om Nimboya te helpen bij zijn zoektocht, maar... ook ik heb redenen om hier te zijn.$B$BDe Bloodscalp-stam is een vijand van onze stam. Als we trofeeën van onze vijanden verzamelen, krijgen we macht over hen. Je kunt onze stam helpen door op onze vijanden te jagen.$B$BZe wonen in het noorden. Dood Bloodscalp-trollen en neem hun bloederige botkettingen mee. Verzamel er veel, en je beloning zal groot zijn.",
  o = "Breng 25 Bloody Bone Necklaces naar Kin'weelay in het Grom'gol Base Camp.",
  p = "Op een dag zullen de Bloodscalps door de Darkspears verpletterd worden! Heb je de kettingen van onze gedoemde vijand?",
  c = "Ah, heel goed. Ik zal ze koken en ze leegzuigen, en de geesten van hun eigenaren worden zwakker terwijl ik hun kettingen tot pasta vermaal!$B$BAlsjeblieft, $N. Hiermee betaal ik mijn schuld aan jou terug.",
  g = { {"zoektocht", "quest, search"}, {"redenen", "reasons (reden)"}, {"stam", "tribe"}, {"trofeeën", "trophies (trofee)"}, {"bloederige", "bloody (bloederig)"}, {"beloning", "reward"}, {"verpletterd", "crushed (verpletteren)"}, {"gedoemde", "doomed (gedoemd)"}, {"leegzuigen", "to suck dry, to leech"}, {"eigenaren", "owners (eigenaar)"}, {"vermaal", "grind (vermalen)"}, {"schuld", "debt"} },
},

[629] = { en = "The Vile Reef", tier = 3,
  t = "Het Vile Reef",
  d = "Lang geleden liet een grote aardschok een oude trollenstad zinken onder het water van de Savage Coast, in het noordwesten. Wij noemen die plek het Vile Reef, want nu wonen er murlocs in de ruïnes van de stad. Ze vallen iedereen aan die te dichtbij komt.$B$BTussen die ruïnes ligt een oude stenen plaat. Daarop staat het oude verhaal van Gri'lek, een held uit de legendes van de trollen. Het verhaal is heilig voor de Darkspear-stam. De plaat is te groot om te verplaatsen, maar ik wil er een scherf van hebben. Die wil ik in een heiligdom bewaren in ons nieuwe thuis in Orgrimmar.",
  o = "Breng een Tablet Shard naar Kin'weelay in het Grom'gol Base Camp.",
  p = "Ik wacht op de Tablet Shard, $N.",
  c = "Dit is goed. Als ik naar Orgrimmar terugkeer, zal ik deze scherf op een heilige plek leggen. Hij zal ons herinneren aan de kracht en de eer van Gri'lek.$B$BDank je, $N. Je daden tonen een groeiende vriendschap met de Darkspear-stam.",
  g = { {"aardschok", "earthquake, shudder of the earth"}, {"zinken", "to sink"}, {"ruïnes", "ruins (ruïne)"}, {"stenen plaat", "stone tablet"}, {"heilig", "sacred, holy"}, {"verplaatsen", "to move (something)"}, {"scherf", "shard"}, {"heiligdom", "shrine, sanctuary"}, {"terugkeer", "return (terugkeren)"}, {"herinneren aan", "to remind of"}, {"daden", "deeds (daad)"}, {"groeiende", "growing (groeien)"} },
},

[638] = { en = "Trollbane", tier = 3,
  t = "Trollbane",
  d = "Nu Thoras Trollbane dood is en Stromgarde in puin ligt, heeft Vol'jin opgedragen dat we alles moeten doen om het legendarische zwaard Trol'kalar uit de handen van de mensen weg te halen. Dan kunnen we het gebruiken in onze komende gevechten tegen de trollen van Zul'Gurub.$b$bZengu, een van onze ervaren jagers, is naar Hammerfall in het noordoosten van de Arathi Highlands gestuurd. Hij moet ervoor zorgen dat we het zwaard in handen krijgen.",
  o = "Reis naar Hammerfall in de Arathi Highlands en spreek met Zengu.",
  c = "Hoe gaat het, $c? De taak die Vol'jin ons heeft gegeven, wordt moeilijk. Alle hulp die je kunt bieden, wordt gewaardeerd en is nodig.",
  g = { {"in puin ligt", "lies in ruins"}, {"opgedragen", "ordered, instructed (opdragen)"}, {"legendarische", "legendary (legendarisch)"}, {"komende", "coming, upcoming"}, {"gevechten", "battles (gevecht)"}, {"ervaren", "experienced, seasoned"}, {"in handen krijgen", "to get hold of"}, {"gewaardeerd", "appreciated (waarderen)"} },
},

[1269] = { en = "Lieutenant Paval Reethe", tier = 3,
  t = "Luitenant Paval Reethe",
  d = "Onder het puin zie je iets glinsteren op de grond. Je veegt het puin en de as weg die aan het voorwerp vastgekoekt zitten. Dan zie je een insigne: een gouden anker op wit, met email op het oppervlak. Het is het teken van Theramore.$b$bOnder het anker staat de naam \"Lieutenant Paval Reethe\" in reliëf.",
  o = "Breng Reethe's Badge naar Krog in Brackenwall Village.",
  p = "Heb je sporen gevonden van wat er bij de Shady Rest Inn is gebeurd?",
  c = "Ik ken deze mens, Paval Reethe. Zielig, zelfs voor iemand van zijn soort. Hij heeft zijn medesoldaten in de steek gelaten en houdt zich nu verborgen in de bossen.$b$bIk heb Ogron eropuit gestuurd om hem op te sporen. Sommige anderen denken dat hij van onze voorraden steelt. Ik denk dat ik Ogron richting het zuidoosten zag gaan.",
  g = { {"luitenant", "lieutenant"}, {"puin", "rubble"}, {"glinsteren", "to glint, to glitter"}, {"veegt", "brush, sweep (vegen)"}, {"vastgekoekt", "caked on (vastkoeken)"}, {"insigne", "insignia, badge"}, {"anker", "anchor"}, {"email", "enamel"}, {"oppervlak", "surface"}, {"in reliëf", "embossed"}, {"zielig", "pathetic, pitiful"}, {"medesoldaten", "fellow soldiers (medesoldaat)"}, {"in de steek gelaten", "deserted, abandoned (in de steek laten)"}, {"eropuit gestuurd", "sent out (eropuit sturen)"}, {"voorraden", "supplies (voorraad)"} },
},

[1270] = { en = "Stinky's Escape", tier = 3,
  t = "Stinky's ontsnapping",
  d = "Mooi, eindelijk iets dat me niet wil opeten!!$B$BIk heb hulp nodig met de beesten hier, en jij bent daar precies geschikt voor, $gmakker:dame;.$B$BEen goblin uit Ratchet die Mebok Mizzyrix heet, heeft bogbean-bladeren nodig voor een drankje of zoiets... Eerlijk gezegd kan het me niet schelen waarom. Hij betaalde goed en ik ken dit moeras, dus hier ben ik.$B$BJammer dat ik omsingeld raakte voordat ik de bogbean vond! Kun je me hier weghelpen, en mijn rug dekken terwijl ik naar de plant van Mebok zoek?",
  o = "Begeleid \"Stinky\" Ignatz en spreek daarna met Mebok Mizzyrix in Ratchet.",
  c = "Stinky was hier met de kruiden die ik hem had gevraagd, en hij vertelde me dat je hem uit de problemen hebt geholpen. Goed werk! Een vriend van Stinky is een vriend van mij!$B$BHij vroeg me om je dit te geven als ik je ooit zag, vlak voordat hij terugliep naar het zuiden, naar het moeras.",
  e = "Help Stinky om Bogbean Leaves te vinden.",
  g = { {"ontsnapping", "escape"}, {"opeten", "to eat up"}, {"geschikt", "suitable, fit"}, {"makker", "buddy, mate"}, {"drankje", "potion, drink"}, {"het kan me niet schelen", "I don't care"}, {"omsingeld", "surrounded (omsingelen)"}, {"weghelpen", "to help get away"}, {"mijn rug dekken", "to watch my back"}, {"begeleid", "escort (begeleiden)"}, {"kruiden", "herbs (kruid)"}, {"uit de problemen", "out of a bind"} },
},

[1276] = { en = "The Black Shield", tier = 3,
  t = "Het zwarte schild",
  d = "Ah, nu weet ik het weer! Mosarn is een gerespecteerde smid in Thunder Bluff. Ik wist dat ik zijn naam al eens ergens had gehoord.$b$bAls dank gaf de Earthen Ring me een harnas dat door Mosarn was gemaakt. Heel goed werk.$b$bMisschien kan hij je meer vertellen over het schild dat hij heeft gemaakt.$b$bHet is geen sterk spoor, maar we hebben niets nuttigs uit Reethe gekregen, dus het is alles wat we hebben.",
  o = "Laat het Blackened Iron Shield zien aan Mosarn in Thunder Bluff.",
  p = "Hallo, $c. Kan ik je ergens mee helpen?",
  c = "Ja, je hebt zeker gelijk. Dit is een schild dat ik heb gemaakt.$b$bMaar ik ben bang dat ik je niet veel meer kan vertellen, $n. Ik maak zoveel verschillende schilden en harnassen dat ik ze niet allemaal kan bijhouden.",
  g = { {"nu weet ik het weer", "now I remember"}, {"gerespecteerde", "respected (gerespecteerd)"}, {"smid", "blacksmith"}, {"als dank", "in thanks"}, {"harnas", "armour, set of armour"}, {"spoor", "lead, trail"}, {"nuttigs", "useful (nuttig)"}, {"gelijk hebben", "to be right"}, {"harnassen", "sets of armour (harnas)"}, {"bijhouden", "to keep track of"} },
},

[1322] = { en = "The Black Shield", tier = 3,
  t = "Het zwarte schild",
  d = "Hmmm, hier op de rand van het schild staat iets geschreven, maar het is moeilijk te lezen door al dat verbrande spul.$b$bIk heb zuur nodig om het duidelijk te maken. Gif van de Darkfang-spinnen in het moeras is goed. Haal wat van hun gifzakken voor me, dan kan ik dit schoonmaken.",
  o = "Verzamel 6 Acidic Venom Sacs voor Do'gol in Brackenwall Village.",
  p = "Heb je die zakken van de spinnen?",
  c = "Ik hou niet van spinnen die zo groot zijn dat ik er niet op kan zitten om ze plat te drukken.$b$bBedankt dat je ze hebt gehaald, $n. Nu scheur ik ze open en giet ik ze over het schild...",
  g = { {"rand", "rim, edge"}, {"verbrande", "burned (verbranden)"}, {"spul", "stuff"}, {"zuur", "acid"}, {"gif", "venom, poison"}, {"spinnen", "spiders (spin)"}, {"gifzakken", "venom sacs (gifzak)"}, {"plat te drukken", "to squish, to press flat (platdrukken)"}, {"scheur", "tear, rip (scheuren)"}, {"giet", "pour (gieten)"} },
