[570] = { en = "Mok'thardin's Enchantment", tier = 3,
  t = "Mok'thardins betovering",
  d = "De Horde moet de kracht van de magie van de jungle begrijpen en daarna gebruiken. Mijn rituelen zijn tot nu toe gelukt. Ik kan zeer krachtige betoveringen maken. Voor jou, dappere $c, zal ik een heel bijzonder voorwerp maken.$b$bBreng me een paar klauwen van Shadowmaw-panters en een slagtand van een tijgerin. Niet elke tand is goed genoeg. Hij moet in perfecte staat zijn.$b$bDe dieren sluipen overal door de jungle, maar je vindt er ook een paar dichtbij: net aan de overkant van de rivier bij de Mizjah Ruins, in het zuidoosten.",
  o = "Far Seer Mok'thardin in het Grom'gol Base Camp wil 8 Shadowmaw Claws en een Pristine Tigress Fang.",
  p = "Welk nieuws breng je?",
  c = "Je kennis van de jungle is groot, $n. Deze exemplaren zijn perfect. Ik zal de geesten bedanken omdat ze zulke mooie dieren hebben geofferd voor de zaak van de Horde.",
  g = { {"betovering", "enchantment"}, {"rituelen", "rituals (ritueel)"}, {"betoveringen", "enchantments (betovering)"}, {"voorwerp", "object, item"}, {"klauwen", "claws (klauw)"}, {"slagtand", "fang, tusk"}, {"tijgerin", "tigress"}, {"in perfecte staat", "in perfect condition"}, {"sluipen", "to lurk, to sneak"}, {"aan de overkant van", "across, on the other side of"}, {"exemplaren", "specimens (exemplaar)"}, {"geofferd", "sacrificed (offeren)"}, {"de zaak", "the cause"} },
},

[585] = { en = "Speaking with Nezzliok", tier = 3,
  t = "Praten met Nezzliok",
  d = "<Het hoofd van Nezzliok spreekt.>$B$BHet is waar. Ik weet waar het kind van de Darkspears naartoe is gebracht. Je hebt me verslagen en mijn geest gebonden, maar ik zeg niets voordat ik tevreden word gesteld!$B$BDe Bloodscalps zijn in oorlog met de Skullsplitters. Wil je mijn gunst winnen? Steel dan 3 van hun trofeeschedels van de Skullsplitters en leg ze hier bij ons neer, zodat mijn geest slaven heeft in de Nether. Eén schedel moet van hun stapel trofeeën in Balia'mah komen, een andere uit Ziata'jai, en de laatste uit Zul'Mamwe.",
  o = "Breng een Balia'mah Trophy, een Ziata'jai Trophy en een Zul'Mamwe Trophy naar de Bubbling Cauldron in het Grom'gol Base Camp.",
  p = "Ik wacht op de schedels...",
  c = "Ja. Deze zullen me goed dienen. Als mijn geest vrij is, ga ik de Nether binnen met drie prachtige dienaren!$B$BJe bent een eer voor je $r-clan, en je hebt me tevredengesteld.",
  g = { {"verslagen", "defeated (verslaan)"}, {"gebonden", "bound (binden)"}, {"tevreden word gesteld", "am appeased (tevredenstellen)"}, {"gunst", "favour"}, {"trofeeschedels", "trophy skulls"}, {"schedel", "skull"}, {"slaven", "slaves (slaaf)"}, {"stapel", "pile, heap"}, {"dienen", "to serve"}, {"dienaren", "servants (dienaar)"}, {"een eer voor", "a credit to"}, {"tevredengesteld", "appeased (tevredenstellen)"} },
},

[571] = { en = "Mok'thardin's Enchantment", tier = 3,
  t = "Mok'thardins betovering",
  d = "Wat ik nu van je nodig heb, is heel moeilijk te krijgen.$b$bOm al deze veren, klauwen en de perfecte tand op hun plek te houden, heb ik een magische band nodig. Alleen een oude pees van een gorilla werkt hiervoor.$b$bJe kunt er alleen een vinden bij een Elder Mistvale Gorilla. Ze zoeken vaak voedsel ten oosten van Booty Bay.$b$bDe pees moet perfect zijn. Misschien moet je er heel wat doden voordat je precies vindt wat ik nodig heb, maar de jacht zal het zeker waard zijn.",
  o = "Breng een Aged Gorilla Sinew naar Far Seer Mok'thardin in Grom'gol.",
  p = "Was het geluk aan jouw kant, $n? Heb je een oude gorillapees kunnen vinden?",
  c = "Een uitstekende pees, $n. Je moeite wordt snel beloond.",
  g = { {"veren", "feathers (veer)"}, {"op hun plek", "in place"}, {"band", "tether, band"}, {"pees", "sinew, tendon"}, {"voedsel zoeken", "to forage"}, {"heel wat", "quite a few"}, {"het waard zijn", "to be worth it"}, {"het geluk aan jouw kant", "fortune on your side"}, {"gorillapees", "gorilla sinew"}, {"uitstekende", "excellent (uitstekend)"}, {"moeite", "effort"}, {"beloond", "rewarded (belonen)"} },
},

[572] = { en = "Mok'thardin's Enchantment", tier = 3,
  t = "Mok'thardins betovering",
  d = "De voorwerpen die je van de katachtige dieren van de Vale hebt verzameld, zijn maar het eerste wat nodig is voor een krachtig betoverd voorwerp. Samen met mijn sjamanistische ritueel worden deze snuisterijen uit de jungle een heel nuttig hulpmiddel om de Horde en de Warchief te helpen.$b$bMaar nu moet je wat Jungle Stalker-veren voor me verzamelen. Volgens de traditie dragen de dieren de veren aan hun armbanden. Je vindt een stam van deze raptors recht ten zuiden van Grom'gol, niet ver van de grote arena.",
  o = "Breng 10 Jungle Stalker Feathers naar Far Seer Mok'thardin in het Grom'gol Base Camp.",
  p = "Heeft je verzamelwerk iets opgeleverd?",
  c = "Uitstekend. Ik zal ze meteen klaarmaken.",
  g = { {"katachtige", "feline (katachtig)"}, {"betoverd", "enchanted (betoveren)"}, {"sjamanistische", "shamanistic (sjamanistisch)"}, {"snuisterijen", "trinkets (snuisterij)"}, {"hulpmiddel", "tool, aid"}, {"volgens de traditie", "traditionally"}, {"armbanden", "armbands (armband)"}, {"recht ten zuiden van", "directly south of"}, {"verzamelwerk", "gathering work"}, {"opgeleverd", "yielded, produced (opleveren)"}, {"klaarmaken", "to prepare"} },
},

[584] = { en = "Bloodscalp Clan Heads", tier = 3,
  t = "Hoofden van de Bloodscalp-clan",
  d = "Yenniku was niet bij de hoofden, en daarvoor dank ik de Grote Slang. Maar we zijn niet dichter bij het vinden van hem.$B$BWe moeten de waarheid weten, en ik vrees dat alleen het opperhoofd van de Bloodscalps en zijn heksendokter die kennen. Ze zijn vijanden van de Darkspear-stam en zullen niet vrij spreken. Dus moeten we de waarheid uit hun dode lippen dwingen!$B$BBreng me de hoofden van Gan'zulah en Nezzliok the Dire en leg ze in deze ketel.$B$BZe zijn diep in Zul'Kunda. Breng hun hoofden... dan laten we ze praten.",
  o = "Breng Gan'zulah's Head en Nezzliok's Head naar de bubbling cauldron in het Grom'gol Base Camp.",
  p = "Het groenige brouwsel in de ketel borrelt.",
  c = "Je legt de hoofden van Gan'zulah en Nezzliok in de ketel...",
  g = { {"Grote Slang", "Great Serpent"}, {"dichter bij", "closer to"}, {"vrees", "fear (vrezen)"}, {"opperhoofd", "chief"}, {"heksendokter", "witch doctor"}, {"vrij spreken", "to speak freely"}, {"dwingen", "to force"}, {"ketel", "cauldron, kettle"}, {"groenige", "greenish (groenig)"}, {"brouwsel", "brew, concoction"}, {"borrelt", "bubbles (borrelen)"} },
},

[598] = { en = "Split Bone Necklace", tier = 3,
  t = "Gespleten botketting",
  d = "Nu je Bloodscalp-trofeeën hebt verzameld, heb ik een andere taak voor je. De trollen van de Skullsplitter-stam wonen in het zuidoosten, en al jaren voeren we oorlog met hen. De Darkspears wonen niet meer in Stranglethorn, maar toch zitten we nog vast aan ons conflict met de Skullsplitters.$B$BDus jaag op hen. Verzamel hun gespleten botkettingen en kom bij me terug. Help ons in onze oorlog, en je verdient de vriendschap van de Darkspears.",
  o = "Breng 25 Split Bone Necklaces naar Kin'weelay in het Grom'gol Base Camp.",
  p = "De Skullsplitters zullen de dag vervloeken waarop ze ons tot oorlog dwongen! Is je taak klaar?",
  c = "Je moet heel sterk zijn om deze kettingen te hebben gekregen, $N. De Skullsplitters vallen voor je neer als jonge boompjes die door een basilisk in de grond worden gestampt!$B$BJe daden zijn een zegen voor ons.",
  g = { {"gespleten", "split (splijten)"}, {"botketting", "bone necklace"}, {"oorlog voeren", "to wage war"}, {"botkettingen", "bone necklaces"}, {"verdient", "earn (verdienen)"}, {"vervloeken", "to curse"}, {"dwongen", "forced (dwingen)"}, {"boompjes", "saplings, little trees (boompje)"}, {"gestampt", "stomped (stampen)"}, {"zegen", "blessing, boon"}, {"zitten we nog vast aan", "we are still bound to (vastzitten aan)"} },
},

[573] = { en = "Mok'thardin's Enchantment", tier = 3,
  t = "Mok'thardins betovering",
  d = "Er is nog maar één laatste ingrediënt nodig om de betovering af te maken.$b$bIn het zuiden, richting de westkust, hoog boven de kliffen, ligt een heilige bron. Over deze bron is veel onenigheid tussen religieuze en mystieke geleerden. Elk volk in Azeroth beweert dat het water van de bron voor hun eigen volk heilig is gemaakt.$b$bMijn laatste verzoek aan jou: breng me Holy Spring Water. Wees gewaarschuwd. Een expeditie van naga-ontdekkingsreizigers is naar de bron opgerukt. Ook met hen moet worden afgerekend.",
  o = "Far Seer Mok'thardin in Grom'gol heeft Holy Spring Water nodig. Hij wil ook dat je 10 Naga Explorers doodt.",
  p = "Ik ben bijna klaar om de betovering af te maken. Heb je gedaan wat ik vroeg?",
  c = "Met dit Holy Spring Water is de ceremoniële halsketting klaar om betoverd te worden.$b$bDraag hem met trots, $n, in naam van de Warchief en ter verdediging van de machtige Horde.",
  g = { {"ingrediënt", "ingredient, reagent"}, {"kliffen", "cliffs, bluffs (klif)"}, {"bron", "spring, source"}, {"onenigheid", "conflict, disagreement"}, {"mystieke", "mystical (mystiek)"}, {"geleerden", "scholars (geleerde)"}, {"beweert", "claims (beweren)"}, {"verzoek", "request"}, {"gewaarschuwd", "warned (waarschuwen)"}, {"ontdekkingsreizigers", "explorers (ontdekkingsreiziger)"}, {"opgerukt", "advanced (oprukken)"}, {"worden afgerekend", "be dealt with (afrekenen met)"}, {"ceremoniële", "ceremonial (ceremonieel)"}, {"halsketting", "choker, necklace"}, {"ter verdediging van", "in defence of"} },
},

[588] = { en = "The Fate of Yenniku", tier = 3,
  t = "Het lot van Yenniku",
  d = "<Nezzliok spreekt.>$B$BJe hebt mij en mijn opperhoofd tevredengesteld, dus ik zal je vertellen wat je wilt ontdekken...$B$BDe jonge Yenniku is verloren voor zijn clan.$B$BHij werd meegenomen door de heksendokter Zanzil the Outcast. Nu beheerst Zanzil hem, lichaam en ziel, en alleen de krachtigste magie zou hem kunnen bevrijden.$B$BMagie die jij niet hebt, $c.$B$BMisschien kunnen je Darkspear-bondgenoten hoop bieden op de redding van Yenniku. Maar dat betwijfel ik.",
  o = "Spreek met Kin'weelay.",
  c = "Zanzil the Outcast??$B$BAls Yenniku wordt vastgehouden door die trol, een gemene en machtige heksendokter, dan vrees ik dat er alleen nog een zwakke hoop over is. Zwak. En zo klein als het kleinste insect.$B$BMaar toch, het is hoop.",
  g = { {"lot", "fate"}, {"tevredengesteld", "appeased (tevredenstellen)"}, {"ontdekken", "to discover"}, {"beheerst", "controls (beheersen)"}, {"lichaam en ziel", "body and soul"}, {"bevrijden", "to free, to set free"}, {"bondgenoten", "allies (bondgenoot)"}, {"redding", "salvation, rescue"}, {"betwijfel", "doubt (betwijfelen)"}, {"vastgehouden", "held (vasthouden)"}, {"gemene", "vile, nasty (gemeen)"}, {"zwakke", "faint, weak (zwak)"} },
},

[589] = { en = "The Singing Crystals", tier = 3,
  t = "De zingende kristallen",
  d = "Legendes vertellen over een juweel dat diep in het hart van Stranglethorn verborgen is. Wij noemen het het Mind's Eye, en het heeft grote krachten. Als jij dit Oog krijgt, kunnen we het misschien gebruiken om de verloren Yenniku terug te halen uit de duisternis.$B$BIk zal de geesten van de jungle raadplegen om het Mind's Eye te vinden. Terwijl ik dat doe, ga jij de Crystalvein Mine in, ten zuidoosten van hier, en verzamel je Pulsing Blue Shards van Ironjaw Basilisks. De scherven zijn zeldzaam, maar we hebben hun magie nodig om het Mind's Eye naar onze wil te buigen.",
  o = "Breng 3 Pulsing Blue Shards naar Kin'weelay in het Grom'gol Base Camp.",
  p = "Heb je de scherven, $N? Ik heb ze nodig voor mijn laatste ritueel, als we het Mind's Eye hebben.",
  c = "Je hebt het goed gedaan, $N. Deze scherven hebben een mooie vorm. Ik hoor ze al voor me zingen.$B$BEn terwijl jij weg was, heb ik met de geesten van de jungle gesproken. Ik weet waar het Mind's Eye ligt...$B$B...En wie het bewaakt.",
  g = { {"zingende", "singing (zingen)"}, {"kristallen", "crystals (kristal)"}, {"juweel", "jewel"}, {"verborgen", "hidden (verbergen)"}, {"duisternis", "darkness"}, {"raadplegen", "to consult"}, {"scherven", "shards (scherf)"}, {"zeldzaam", "rare"}, {"naar onze wil te buigen", "to bend to our will"}, {"vorm", "shape, form"}, {"bewaakt", "guards (bewaken)"} },
},

[586] = { en = "Speaking with Gan'zulah", tier = 4,
  t = "Praten met Gan'zulah",
  d = "<Het hoofd van Gan'zulah spreekt.>$B$BIk vervloek je! En ik vervloek je voorouders!!$B$BAlleen bloed en wraak kunnen mijn woede afkoelen. Dus als je dat wilt, doe dan... dit:$B$BWerp jezelf in het hart van de Skullsplitters in het oosten. Dood de felste van hen, en als je het overleeft... loop je dan stuk op hun opperhoofd, Ana'thek the Cruel. Ha! Breng me zijn verbrijzelde harnas, als je kunt!$B$BMoge hij je ledematen afrukken en je laten liggen, zodat je wegrot en door aasdieren wordt opgegeten.",
  o = "Dood 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters en 4 Skullsplitter Berserkers.$B$BBreng de Broken Armor of Ana'thek naar de Bubbling Cauldron in het Grom'gol Base Camp.",
  p = "Ook al kookt mijn eigen vlees van mijn schedel, ik kan je angst nog steeds ruiken.$B$BHa! Je zult mijn taak nooit volbrengen...",
  c = "Ik wil het niet geloven, maar ik kan niet ontkennen wat je hebt gedaan. En mijn woede wordt minder, nu Ana'thek verslagen is.$B$BJe kracht zal je tot grote daden brengen, $N. Maar op een dag... zie ik je in de Nether, en dan meten we opnieuw onze krachten.$B$BIk zal wachten.",
  g = { {"vervloek", "curse (vervloeken)"}, {"voorouders", "ancestors (voorouder)"}, {"wraak", "revenge"}, {"afkoelen", "to cool down"}, {"werp", "throw, hurl (werpen)"}, {"felste", "fiercest (fel)"}, {"loop je dan stuk op", "then break yourself against (stuklopen op)"}, {"verbrijzelde", "shattered (verbrijzelen)"}, {"harnas", "armour"}, {"moge", "may (archaic wish form of mogen)"}, {"ledematen", "limbs"}, {"afrukken", "to tear off"}, {"wegrot", "rot away (wegrotten)"}, {"aasdieren", "carrion eaters, scavengers (aasdier)"}, {"volbrengen", "to complete, to accomplish"} },
},

[591] = { en = "The Mind's Eye", tier = 4,
  t = "Het Mind's Eye",
  d = "Het Mind's Eye is in handen van een ogermagiër, ten oosten van hier, diep in de ogerheuvel van Mosh'Ogg. Zijn naam is Mai'Zoth. Ik ken hem uit de tijd dat de Darkspears in Stranglethorn woonden. Hij is wreed, en zijn magie is sterk.$B$BEn als hij het Mind's Eye heeft, dan is zijn magie nog sterker.$B$BJe moet Mai'Zoth onder ogen komen en het Mind's Eye van hem afpakken. Het is een gevaarlijke taak, maar het is de enige hoop die we hebben om Yenniku te redden.",
  o = "Breng het Mind's Eye naar Kin'weelay in het Grom'gol Base Camp.",
  p = "Gegroet, $N. De geesten zingen lof over je moed, maar ze vertellen me geen verhalen over je tocht tegen Mai'Zoth.$B$BHeb je het Oog?",
  c = "Je hebt het oog teruggehaald! Jouw kracht is iets uit de legendes, $N!$b$bEn om het Oog te krijgen, moet je Mai'Zoth hebben verslagen en hem naar de Nether hebben gestuurd. Daarom wilden de geesten eerder niets over hem zeggen.$b$bHet is goed dat hij weg is uit de wereld van vlees en bot, maar nu hij in het rijk van de geesten is... vrees ik dat hij een nieuwe heerschappij zal beginnen.$b$bMaar daar maken we ons later zorgen over. Nu moet ik een ritueel uitvoeren om het Mind's Eye naar onze wensen te buigen...",
  g = { {"in handen van", "in the hands of, held by"}, {"ogermagiër", "ogre mage"}, {"ogerheuvel", "ogre mound"}, {"wreed", "vicious, cruel"}, {"onder ogen komen", "to face"}, {"afpakken", "to take away, to wrest"}, {"gevaarlijke", "perilous, dangerous (gevaarlijk)"}, {"gegroet", "greetings"}, {"lof", "praise"}, {"moed", "bravery, courage"}, {"tocht", "journey, quest"}, {"rijk", "realm"}, {"heerschappij", "reign, rule"}, {"uitvoeren", "to perform, to carry out"}, {"wensen", "wishes, needs (wens)"} },
},

[592] = { en = "Saving Yenniku", tier = 4,
  t = "Yenniku redden",
  d = "Ik heb het Mind's Eye omgevormd tot een Soul Gem. Het heeft een dubbel doel: je moet het gebruiken om Yenniku te verdoven, en als hij verdoofd is, leg je het op zijn hoofd om zijn ziel te vangen.$B$BBreng daarna de steen naar Nimboya.$B$BYenniku woont bij Zanzil the Outcast, in de Ruins of Aboraz, langs de Crystal Shore op de verre Cape of Stranglethorn.",
  o = "Breng de Filled Soul Gem naar Nimboya.",
  p = "$N. Kin'weelay vertelde me dat je op pad bent gegaan om Yenniku te vangen.$b$bIs het waar? Heb je hem?",
  c = "Het is je gelukt! Je hebt Yenniku bevrijd van de wil van Zanzil, en de missie voltooid waarvan ik dacht dat die zo hopeloos was.$b$bOnze stam zal je naam in liederen gedenken, $N, en we zullen je verhaal in steen hakken, zodat het voor altijd blijft bestaan.",
  g = { {"omgevormd", "reshaped (omvormen)"}, {"dubbel doel", "twofold purpose"}, {"verdoven", "to stun"}, {"verdoofd", "stunned (verdoven)"}, {"vangen", "to catch, to capture"}, {"verre", "distant (ver)"}, {"op pad", "on the way, setting out"}, {"voltooid", "completed (voltooien)"}, {"hopeloos", "hopeless, desperate"}, {"liederen", "songs (lied)"}, {"gedenken", "to commemorate, to remember"}, {"in steen hakken", "to carve in stone"} },
},

[593] = { en = "Filling the Soul Gem", tier = 4,
  t = "De Soul Gem vullen",
  p = "Yenniku staat verdoofd voor je, met zijn gedachten op een andere plek...",
  c = "Je legt de Soul Gem op zijn voorhoofd. Hij huivert terwijl zijn ziel wordt opgezogen. Zijn ziel verlaat zijn lichaam en laat een lege huls zonder verstand achter.",
  g = { {"vullen", "to fill"}, {"verdoofd", "stunned (verdoven)"}, {"gedachten", "thoughts, mind (gedachte)"}, {"voorhoofd", "forehead"}, {"huivert", "shudders (huiveren)"}, {"opgezogen", "sucked in (opzuigen)"}, {"verlaat", "leaves (verlaten)"}, {"huls", "husk, shell"}, {"verstand", "mind, reason"} },
},

[8551] = { en = "The Captain's Chest", tier = 4,
  t = "De kist van de kapitein",
  d = "Vroeger voer ik met een schip van hier helemaal naar Ratchet, in Kalimdor. Ik was een succesvolle kapitein met een uitstekende reputatie.$B$BTot...$B$BDie vervloekte zeereuzen hebben me geruïneerd! Ze sloegen mijn schip kapot, doodden mijn bemanning en zetten me in een reddingsboot naar Booty Bay. En een van de reuzen, Gorlash, stal mijn kapiteinskist. Hij zei dat hij hem wilde als snuifdoos. Wat een lef!$B$BIk hoor dat Gorlash langs de kust ten oosten van hier rondzwerft. Vind hem en haal mijn kist terug! Doe dat, en je hebt de dankbaarheid van een kapitein verdiend.",
  o = "Breng Smotts' Chest naar Hecklebury Smotts in Booty Bay.",
  p = "Ahoi, $N! Heb je Gorlash gevonden? Die kist was mijn lievelingskist, en er zit een geheim vak in waarin mijn grootste schatten zaten!",
  c = "Je hebt hem gevonden! O, wat een blije dag is dit! Dank je, $N. Nu ik mijn kist terug heb, is een deel van het vuur in mij afgekoeld.$B$BMaar mijn wraak is nog niet compleet...",
  g = { {"kist", "chest"}, {"voer", "sailed (varen)"}, {"reputatie", "reputation"}, {"vervloekte", "cursed (vervloekt)"}, {"zeereuzen", "sea giants (zeereus)"}, {"geruïneerd", "ruined (ruïneren)"}, {"bemanning", "crew"}, {"reddingsboot", "lifeboat"}, {"kapiteinskist", "captain's chest"}, {"snuifdoos", "snuffbox"}, {"wat een lef", "the nerve, what cheek"}, {"rondzwerft", "wanders around (rondzwerven)"}, {"dankbaarheid", "gratitude"}, {"lievelingskist", "favourite chest"}, {"geheim vak", "hidden compartment"} },
},

[8553] = { en = "The Captain's Cutlass", tier = 4,
  t = "De kortelas van de kapitein",
  d = "Nadat ik mijn eerste schip aan die reuzen was kwijtgeraakt, kocht ik een ander. Ik noemde het Smotts' Revenge, vulde het met voorraden en bemanning, en ging op zoek naar de schurken. Ik vond ze, maar... ze versloegen me. Ze sloegen de Smotts' Revenge kapot, doodden mijn tweede bemanning en zetten me in nog een reddingsboot.$B$BDeze keer stal een andere reus, Negolash, mijn kortelas.$B$BGa de strijd aan met Negolash en breng me mijn kortelas!$B$BSpreek met Sprogger. Hij was mijn kok op de Smotts' Revenge en heeft de laatste aanval overleefd. Hij kan je helpen de reus te vinden.",
  o = "Spreek met Sprogger.",
  c = "Hallo hallo, $N. De kapitein zei dat je achter Negolash aan gaat, hè?",
  g = { {"kortelas", "cutlass"}, {"kwijtgeraakt", "lost (kwijtraken)"}, {"voorraden", "supplies (voorraad)"}, {"bemanning", "crew"}, {"schurken", "villains (schurk)"}, {"versloegen", "beat, defeated (verslaan)"}, {"reddingsboot", "lifeboat"}, {"de strijd aangaan met", "to face, to take on"}, {"kok", "cook"}, {"overleefd", "survived (overleven)"}, {"achter iemand aan gaan", "to go after someone"} },
},

[8554] = { en = "Facing Negolash", tier = 4,
  t = "Oog in oog met Negolash",
  d = "Negolash is een hongerige reus.$B$BToen de reuzen ons schip vernielden, ging Negolash meteen naar mijn keuken. Hij had geen honger naar bemanningsleden, zoals de andere reuzen. Negolash wilde wijn... en mijn Barbecued Buzzard Wings. Dat is mijn specialiteit, en ik moest er helemaal voor naar de Badlands om het recept te halen!$B$BAls je de reus wilt lokken, haal dan wat wijn en een flinke stapel gierenvleugels. Leg ze in onze oude reddingsboot, ten zuidoosten van hier langs de kust. Als Negolash al dat eten ruikt, komt hij zeker!",
  o = "Breng 10 Barbecued Buzzard Wings en 5 flessen Junglevine Wine naar Captain Smotts' Lifeboat.$B$BDood Negolash en breng Smotts' Cutlass naar Captain Smotts in Stranglethorn.",
  p = "Heb je mijn kortelas, $N?",
  c = "Je hebt mijn kortelas van Negolash afgepakt! Ik kan mijn geluk niet geloven, $N! Sinds ik jou ken, is mijn geluk beter geworden, daar kun je zeker van zijn!$B$BDank je! En als ik ooit een nieuw schip krijg en jij de zeeën wilt bevaren, dan ben je mijn eregast.",
  g = { {"oog in oog met", "face to face with"}, {"hongerige", "hungry (hongerig)"}, {"vernielden", "destroyed (vernielen)"}, {"bemanningsleden", "crew members (bemanningslid)"}, {"specialiteit", "speciality"}, {"recept", "recipe"}, {"lokken", "to lure"}, {"flinke stapel", "big heap"}, {"gierenvleugels", "buzzard wings (gierenvleugel)"}, {"reddingsboot", "lifeboat"}, {"flessen", "bottles (fles)"}, {"kortelas", "cutlass"}, {"afgepakt", "taken away (afpakken)"}, {"daar kun je zeker van zijn", "make no mistake"}, {"bevaren", "to sail"} },
},

})

